package android.view;import java.util.*;public class ViewGroup extends View{public List<View> children=new ArrayList<>();public ViewGroup(Object a){super(a);}public void addView(View v){children.add(v);v.parent=this;}public void addView(View v,Object p){v.params=p;addView(v);}public void removeView(View v){children.remove(v);v.parent=null;}public void removeAllViews(){for(View v:children)v.parent=null;children.clear();}public View getChildAt(int i){return children.get(i);}public int getChildCount(){return children.size();}public static class LayoutParams{public static final int WRAP_CONTENT=-2;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}}